def canonical_shape(value: str) -> str:
    # Internal handlers are valid normalized values. Metadata validation uses
    # METADATA_SHAPES separately and retains the fixed public source name set.
    if isinstance(value,str) and value in SOURCE_HANDLERS:return value
    if not isinstance(value, str) or value not in SHAPE_ALIASES:
        raise MermaidError(f"Unknown flowchart shape {value!r}", code="UNSUPPORTED_SHAPE")
    return SHAPE_ALIASES[value]


def is_valid_shape(value: str) -> bool:
    return isinstance(value, str) and (value in SHAPE_ALIASES or value in SOURCE_HANDLERS)
